const API = 'https://app.cubehosting.com.br/api';
const headers = { Authorization: `Bearer ${process.env.CUBE_API_KEY}` };

const res = await fetch(`${API}/projects/${process.env.PROJECT_ID}/logs?lines=100`, { headers });
const decoder = new TextDecoder();
let rest = '';
for await (const chunk of res.body) {
  const events = (rest + decoder.decode(chunk, { stream: true })).split('\n\n');
  rest = events.pop();
  for (const event of events) {
    const data = event.split('\n').find((l) => l.startsWith('data: '));
    if (event.startsWith('event: line') && data) console.log(JSON.parse(data.slice(6)).text);
  }
}

