const API = 'https://app.cubehosting.com.br/api';
const headers = { Authorization: `Bearer ${process.env.CUBE_API_KEY}` };

const res = await fetch(`${API}/projects/${process.env.PROJECT_ID}/metrics?window=24h`, { headers });
const { points, memoryLimitMb } = await res.json();
const peak = points.length ? Math.max(...points.map((p) => p.memoryMb)) : 0;
console.log(`Pico de memória: ${peak} de ${memoryLimitMb} MB`);

const API = 'https://app.cubehosting.com.br/api';
const headers = { Authorization: `Bearer ${process.env.CUBE_API_KEY}` };

const res = await fetch(`${API}/projects/${process.env.PROJECT_ID}/variables`, { headers });
const { variables } = await res.json();
console.log(variables.map((v) => v.name)); // [ 'TOKEN', 'PREFIX' ]

const API = 'https://app.cubehosting.com.br/api';
const headers = { Authorization: `Bearer ${process.env.CUBE_API_KEY}` };

const res = await fetch(`${API}/projects/${process.env.PROJECT_ID}/variables`, {
  method: 'PUT',
  headers: { ...headers, 'Content-Type': 'application/json' },
  body: JSON.stringify({
    variables: [
      { name: 'TOKEN', value: process.env.BOT_TOKEN },
      { name: 'PREFIX' }, // sem value: mantém o valor guardado
    ],
  }),
});
console.log(await res.json()); // { variables: [...], isRestartRequired: true }

import os
import requests

API = "https://app.cubehosting.com.br/api"
headers = {"Authorization": f"Bearer {os.environ['CUBE_API_KEY']}"}

r = requests.put(
    f"{API}/projects/{os.environ['PROJECT_ID']}/variables",
    headers=headers,
    json={
        "variables": [
            {"name": "TOKEN", "value": os.environ["BOT_TOKEN"]},
            {"name": "PREFIX"},  # sem value: mantém o valor guardado
        ]
    },
    timeout=30,
)
print(r.json())
